"""Typed payload models.

The models validate the decoded frame shape and hand the raw template strings to
the byte-program context, which produces the byte sequences the frame adapter
emits.  Nothing here expands a payload eagerly: a compiled frame only owns
compressed sequence nodes.
"""
import logging
from typing import Any, Dict, List, Literal, Optional, Tuple

from pydantic import (BaseModel, ConfigDict, Field, StrictBool, StrictInt,
                      StrictStr, ValidationError, model_validator)

from modules.byte_program import MAX, Context

logger = logging.getLogger("PayloadEvaluator")

PAIRS = 128


class _Frame(BaseModel):
    model_config = ConfigDict(extra='forbid', frozen=True)

    def compile(self, context, case_index, frame_index):
        raise NotImplementedError


class H3HeaderFrame(_Frame):
    """Header block frame: exactly one of mapping or pair-list form."""

    Type: Literal["headers"] = Field(..., description="Fixed value, 'headers'")
    headers_kv: Optional[Dict[StrictStr, StrictStr]] = Field(
        None, description="[Recommended] Header mapping, e.g. {':method': 'GET'}")
    data_to_transfered: Optional[List[Tuple[StrictStr, StrictStr]]] = Field(
        None, description="Two-string array form [[k, v], ...]")
    End_Stream: StrictBool = Field(False, description="End the stream after this frame.")

    def pairs(self):
        if self.headers_kv is not None:
            return list(self.headers_kv.items())
        return list(self.data_to_transfered)

    @model_validator(mode='after')
    def process_headers(self):
        mapping = self.headers_kv
        listing = self.data_to_transfered
        if (mapping is None) == (listing is None):
            raise ValueError("exactly one of headers_kv/data_to_transfered")
        if len(self.pairs()) > PAIRS:
            raise ValueError('header block size')
        return self

    def compile(self, context, case_index, frame_index):
        coordinate = 'case/%d/frame/%d' % (case_index, frame_index)
        pairs = []
        for index, (name, value) in enumerate(self.pairs()):
            pairs.append((context.template(name, coordinate + '/h/%d/n' % index),
                          context.template(value, coordinate + '/h/%d/v' % index)))
        return {'Type': 'headers', 'End_Stream': self.End_Stream,
                'data_to_transfered': pairs}


class H3DataFrame(_Frame):
    """data/datagram payload frame carrying one template string."""

    Type: Literal["data", "datagram"] = Field(..., description="'data' or 'datagram'")
    data_to_transfered: StrictStr = Field(..., description="Payload template.")
    End_Stream: StrictBool = Field(True, description="End the stream after this frame.")

    def compile(self, context, case_index, frame_index):
        coordinate = 'case/%d/frame/%d/data' % (case_index, frame_index)
        return {'Type': self.Type, 'End_Stream': self.End_Stream,
                'data_to_transfered': context.template(self.data_to_transfered,
                                                       coordinate)}


class H3SleepFrame(_Frame):
    """Virtual pause; emits nothing and cannot finish a request."""

    Type: Literal["sleep"] = Field(..., description="Fixed value, 'sleep'")
    Time_to_Stop: StrictInt = Field(..., ge=0, le=MAX,
                                    description="Pause duration (milliseconds)")

    def compile(self, context, case_index, frame_index):
        return {'Type': 'sleep', 'End_Stream': False,
                'Time_to_Stop': self.Time_to_Stop, 'data_to_transfered': None}


class FuzzingPayload(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    test_cases: Dict[str, List[Any]] = Field(
        ..., description="Case name to compiled frame list.")


MODELS = {'headers': H3HeaderFrame, 'data': H3DataFrame,
          'datagram': H3DataFrame, 'sleep': H3SleepFrame}


def compile_cases(cases, context):
    """Validate every frame of every case, then compile all templates."""
    if not isinstance(context, Context):
        raise ValidationError  # pragma: no cover - defensive
    data = {}
    for case_index, case in enumerate(cases):
        frames = []
        for frame_index, frame in enumerate(case['frames']):
            if type(frame) is not dict:
                raise ValueError('frame')
            kind = frame.get('Type')
            model = MODELS.get(kind) if type(kind) is str else None
            if model is None:
                raise ValueError('frame type')
            try:
                parsed = model.model_validate(frame)
            except ValidationError:
                raise ValueError('frame shape') from None
            frames.append(parsed.compile(context, case_index, frame_index))
        data[case['name']] = frames
    return FuzzingPayload.model_construct(test_cases=data)
PYEOF
